import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { api, ApiError, tokens, type Contact, type Emergency, type History, type Journey, type LocationPoint, type Notification, type PublicShare, type Resource, type SafetyTimer, type Settings, type User } from './api';
import { useCountdown, useInterval, useRealtime } from './hooks';
import { Activity, AlertCircle, ArrowRight, Bell, Bike, BookOpen, Building2, CalendarClock, Camera, Check, CheckCircle2, ChevronRight, CircleHelp, Clock3, Copy, Crosshair, Ellipsis, Eye, FileAudio, Fingerprint, MoreHorizontal, Flag, Globe2, HeartHandshake, Home, Hospital, KeyRound, LifeBuoy, Lock, LogOut, MapPin, Menu, MessageCircle, Moon, Navigation, NotebookTabs, Phone, Plus, Radio, RefreshCw, Route, Settings2, Shield, ShieldCheck, Siren, Smartphone, Sparkles, Timer, Trash2, TriangleAlert, UserRound, UsersRound, Vibrate, Volume2, X, Zap } from './icons';
import { Button, Card, CardHeader, EmptyState, Field, IconButton, LocationBadge, Logo, MiniMap, Modal, Pill, QuickLink, SectionHeading, SelectField, Skeleton, StatusDot, TimeAgo, Toast, Toggle } from './components';

const fallbackSettings: Settings = { sosCountdown: 5, journeyTimeoutMinutes: 10, deviationSensitivity: 'medium', checkInGraceMinutes: 5, publicLinkHours: 24, notificationPreferences: { push: true, sms: true, email: true }, privacy: { locationSharing: false, evidenceRetentionDays: 30, historyRetentionDays: 180 }, escalation: { notifyContacts: true, includeLastKnownLocation: true } };

type View = 'overview' | 'emergency' | 'journeys' | 'timer' | 'contacts' | 'resources' | 'history' | 'settings' | 'admin';
type ToastTone = 'success' | 'danger' | 'info';
type ToastState = { message: string; tone?: ToastTone } | null;
type HistoryRow = { id: string; type: string; title: string; status: string; date: string; detail: string };


function getLocation(): Promise<LocationPoint | undefined> {
  return new Promise((resolve) => {
    if (!navigator.geolocation) return resolve(undefined);
    navigator.geolocation.getCurrentPosition((position) => resolve({ latitude: position.coords.latitude, longitude: position.coords.longitude, accuracy: position.coords.accuracy, speed: position.coords.speed ?? undefined, heading: position.coords.heading ?? undefined, timestamp: new Date().toISOString() }), () => resolve(undefined), { enableHighAccuracy: true, timeout: 3500, maximumAge: 30_000 });
  });
}

export function App() {
  const [user, setUser] = useState<User | null>(null);
  const [booting, setBooting] = useState(true);
  const [authMode, setAuthMode] = useState<'login' | 'signup'>('login');
  const [toast, setToast] = useState<ToastState>(null);
  const [publicShare, setPublicShare] = useState<PublicShare | null>(null);
  const [publicError, setPublicError] = useState('');
  const publicToken = window.location.pathname.startsWith('/emergency/') ? window.location.pathname.split('/').filter(Boolean)[1] : undefined;

  useEffect(() => {
    const onLogout = () => { setUser(null); setBooting(false); };
    window.addEventListener('abhaya:logout', onLogout);
    const boot = async () => {
      if (publicToken) {
        try { setPublicShare(await api.publicShare(publicToken)); } catch (error) { setPublicError(error instanceof ApiError ? error.message : 'This safety link is unavailable.'); }
        setBooting(false);
        return;
      }
      if (!tokens.access) { setBooting(false); return; }
      try { const result = await api.profile(); setUser(result.user); } catch { tokens.clear(); }
      setBooting(false);
    };
    void boot();
    return () => window.removeEventListener('abhaya:logout', onLogout);
  }, [publicToken]);

  const onAuth = (result: { user: User; accessToken: string; refreshToken: string }) => { tokens.set(result.accessToken, result.refreshToken); setUser(result.user); setToast({ message: 'Welcome to ABHAYA. Your safety settings are ready.' }); };
  const onLogout = async () => { try { await api.logout(); } catch { /* token is cleared below */ } tokens.clear(); setUser(null); };
  if (booting) return <div className="boot-screen"><Logo /><div className="boot-loader"><span /><span /><span /></div><p>Preparing your private safety space…</p></div>;
  if (publicToken) return publicShare ? <PublicEmergencyViewer share={publicShare} /> : <div className="public-error"><Logo /><div className="empty-icon"><Lock size={22} /></div><h1>Safety link unavailable</h1><p>{publicError || 'This temporary link may have expired or been revoked.'}</p><span>ABHAYA links are time-limited and never expose private account details.</span></div>;
  if (!user) return <AuthScreen mode={authMode} setMode={setAuthMode} onAuth={onAuth} />;
  return <Dashboard user={user} setUser={setUser} onLogout={onLogout} toast={toast} setToast={setToast} />;
}


function PublicEmergencyViewer({ share }: { share: PublicShare }) {
  const safe = share.safe || ['RESOLVED', 'COMPLETED'].includes(share.status);
  return <div className={`public-viewer ${safe ? 'public-viewer--safe' : ''}`}><div className="public-top"><Logo /><Pill tone={safe ? 'success' : 'danger'} dot>{safe ? 'Marked safe' : 'Live safety link'}</Pill></div><div className="public-center"><div className="public-symbol">{safe ? <CheckCircle2 size={36} /> : <Radio size={36} />}</div><span className="eyebrow">Temporary emergency view</span><h1>{share.firstName} is {safe ? 'safe' : 'sharing a live status'}</h1><p>{safe ? 'This session has ended. Location sharing is no longer active.' : 'A trusted person shared this limited view with you. Keep this page open for the latest status.'}</p><div className="public-status"><div><span>Status</span><strong>{safe ? 'Safe' : share.status.replace(/_/g, ' ')}</strong></div><div><span>Last update</span><strong>{new Date(share.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</strong></div></div>{share.lastKnownLocation && <div className="public-location"><MiniMap active={!safe} markers={0} lat={share.lastKnownLocation.latitude} lng={share.lastKnownLocation.longitude} /><div><MapPin size={15} /><span>Last known location · {new Date(share.timestamp).toLocaleString([], { day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit' })}</span></div></div>}<div className="public-expiry"><Lock size={13} /> This link expires {new Date(share.expiresAt).toLocaleString([], { day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit' })}. It never shows medical or account data.</div></div><div className="public-footer"><ShieldCheck size={15} /> Powered by ABHAYA 1107 · Privacy-first by design</div></div>;
}

function AuthScreen({ mode, setMode, onAuth }: { mode: 'login' | 'signup'; setMode: (mode: 'login' | 'signup') => void; onAuth: (result: { user: User; accessToken: string; refreshToken: string }) => void }) {
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [message, setMessage] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [form, setForm] = useState({ fullName: '', email: 'demo@abhaya.app', phone: '+91 98765 43210', password: 'Password123!' });
  const update = (key: string, value: string) => setForm((current) => ({ ...current, [key]: value }));
  const submit = async (event: React.FormEvent) => {
    event.preventDefault(); setLoading(true); setError(''); setMessage('');
    try { const result = mode === 'login' ? await api.login({ email: form.email, password: form.password }) : await api.signup(form); onAuth(result); } catch (err) { setError(err instanceof ApiError ? err.message : 'Unable to connect. Please try again.'); } finally { setLoading(false); }
  };
  return <div className="auth-layout">
    <div className="auth-visual">
      <div className="auth-visual-top"><Logo /><Pill tone="success" dot>Private by default</Pill></div>
      <div className="auth-visual-copy"><span className="auth-kicker"><Sparkles size={14} /> Everyday confidence, when it matters</span><h1>Feel safer.<br /><em>Move freely.</em></h1><p>ABHAYA keeps trusted people connected during the moments that matter — without tracking you when you do not ask it to.</p></div>
      <div className="auth-orbit"><div className="orbit-ring orbit-ring--one" /><div className="orbit-ring orbit-ring--two" /><div className="orbit-center"><ShieldCheck size={30} /><span>1107</span></div><div className="orbit-tag orbit-tag--one"><MapPin size={14} /> Your location</div><div className="orbit-tag orbit-tag--two"><HeartHandshake size={14} /> Trusted circle</div></div>
      <div className="auth-visual-foot"><span><Lock size={14} /> End-to-end privacy principles</span><span><Shield size={14} /> No continuous tracking</span></div>
    </div>
    <div className="auth-panel">
      <div className="auth-panel-inner">
        <div className="mobile-auth-logo"><Logo /></div>
        <div className="auth-tabs"><button className={mode === 'login' ? 'active' : ''} onClick={() => { setMode('login'); setError(''); }}>Sign in</button><button className={mode === 'signup' ? 'active' : ''} onClick={() => { setMode('signup'); setError(''); }}>Create account</button></div>
        <div className="auth-heading"><h2>{mode === 'login' ? 'Welcome back' : 'Build your safety circle'}</h2><p>{mode === 'login' ? 'Your trusted support is one calm tap away.' : 'Set up a private space for safer everyday journeys.'}</p></div>
        {error && <div className="form-alert form-alert--error"><AlertCircle size={16} />{error}</div>}
        {message && <div className="form-alert form-alert--success"><CheckCircle2 size={16} />{message}</div>}
        <form onSubmit={submit} className="auth-form">
          {mode === 'signup' && <Field label="Full name" placeholder="e.g. Ananya Rao" value={form.fullName} onChange={(e) => update('fullName', e.target.value)} required autoComplete="name" />}
          <Field label="Email address" type="email" placeholder="you@example.com" value={form.email} onChange={(e) => update('email', e.target.value)} required autoComplete="email" />
          {mode === 'signup' && <Field label="Phone number" type="tel" placeholder="+91 98765 43210" value={form.phone} onChange={(e) => update('phone', e.target.value)} required autoComplete="tel" />}
          <label className="field"><span className="field-label">Password</span><span className="password-wrap"><input type={showPassword ? 'text' : 'password'} value={form.password} onChange={(e) => update('password', e.target.value)} required autoComplete={mode === 'login' ? 'current-password' : 'new-password'} /><button type="button" onClick={() => setShowPassword((value) => !value)} aria-label={showPassword ? 'Hide password' : 'Show password'}>{showPassword ? <Eye size={16} /> : <Eye size={16} />}</button></span></label>
          {mode === 'login' && <div className="auth-inline"><label className="check-label"><input type="checkbox" defaultChecked /> <span>Remember this device</span></label><button type="button" className="link-button" onClick={async () => { try { const result = await api.forgotPassword(form.email); setMessage(result.devToken ? `Demo reset token: ${result.devToken.slice(0, 10)}…` : 'If that account exists, reset instructions were sent.'); } catch (err) { setError(err instanceof ApiError ? err.message : 'Could not request a reset.'); } }}>Forgot password?</button></div>}
          {mode === 'signup' && <label className="check-label terms"><input type="checkbox" required /> <span>I understand location sharing starts only when I begin a safety session.</span></label>}
          <Button type="submit" size="lg" className="auth-submit" loading={loading} icon={mode === 'login' ? <ArrowRight size={17} /> : <ShieldCheck size={17} />}>{mode === 'login' ? 'Enter my safety space' : 'Create my account'}</Button>
        </form>
        {mode === 'login' && <div className="demo-login"><div className="demo-login-head"><span className="demo-dot" /><span>Demo mode is on</span></div><p>Use the prefilled account to explore the full workflow. No paid services required.</p><button onClick={() => { update('email', 'demo@abhaya.app'); update('password', 'Password123!'); }}>Use demo access <ArrowRight size={14} /></button></div>}
        <div className="auth-footnote"><Lock size={13} /> Your emergency data stays private and expires according to your settings.</div>
      </div>
    </div>
  </div>;
}

function Dashboard({ user, setUser, onLogout, toast, setToast }: { user: User; setUser: (user: User) => void; onLogout: () => void; toast: ToastState; setToast: (toast: ToastState) => void }) {
  const [view, setView] = useState<View>('overview');
  const [mobileNav, setMobileNav] = useState(false);
  const [contacts, setContacts] = useState<Contact[]>([]);
  const [activeEmergency, setActiveEmergency] = useState<Emergency | null>(null);
  const [journeys, setJourneys] = useState<Journey[]>([]);
  const [timers, setTimers] = useState<SafetyTimer[]>([]);
  const [resources, setResources] = useState<Resource[]>([]);
  const [notifications, setNotifications] = useState<Notification[]>([]);
  const [history, setHistory] = useState<History | null>(null);
  const [loading, setLoading] = useState(true);
  const [refreshing, setRefreshing] = useState(false);
  const [error, setError] = useState('');
  const [shareUrl, setShareUrl] = useState('');
  const [showSos, setShowSos] = useState(false);
  const [sosSeconds, setSosSeconds] = useState(5);
  const [locationLive, setLocationLive] = useState(false);
  const settings = user.settings ?? fallbackSettings;

  const notify = useCallback((message: string, tone: ToastTone = 'success') => setToast({ message, tone }), [setToast]);
  const loadData = useCallback(async (quiet = false) => {
    if (!quiet) setLoading(true); else setRefreshing(true);
    setError('');
    const results = await Promise.allSettled([api.activeEmergency(), api.contacts(), api.journeys(), api.timers(), api.resources(), api.notifications(), api.history(), api.profile()]);
    const [emergencyResult, contactsResult, journeysResult, timersResult, resourcesResult, notificationsResult, historyResult, profileResult] = results;
    if (emergencyResult.status === 'fulfilled') setActiveEmergency(emergencyResult.value.emergency);
    if (contactsResult.status === 'fulfilled') setContacts(contactsResult.value.contacts);
    if (journeysResult.status === 'fulfilled') setJourneys(journeysResult.value.journeys);
    if (timersResult.status === 'fulfilled') setTimers(timersResult.value.timers);
    if (resourcesResult.status === 'fulfilled') setResources(resourcesResult.value.resources);
    if (notificationsResult.status === 'fulfilled') setNotifications(notificationsResult.value.notifications);
    if (historyResult.status === 'fulfilled') setHistory(historyResult.value);
    if (profileResult.status === 'fulfilled') setUser(profileResult.value.user);
    if (results.every((result) => result.status === 'rejected')) setError('We could not reach the safety service. Your local screen is still available — retry when connected.');
    setLoading(false); setRefreshing(false);
  }, [setUser]);
  useEffect(() => { void loadData(); }, [loadData]);
  useRealtime((event) => {
    const payload = event.payload;
    if (payload?.kind === 'emergency.updated') setActiveEmergency(payload.emergency?.status && !['RESOLVED', 'CANCELLED'].includes(payload.emergency.status) ? payload.emergency : null);
    if (payload?.kind === 'location.updated' && activeEmergency?.id === payload.emergencyId) setActiveEmergency((current) => current ? { ...current, location: payload.location, lastLocationAt: payload.location.timestamp } : current);
    if (payload?.kind === 'journey.updated' || payload?.kind === 'journey.anomaly') setJourneys((current) => current.map((journey) => journey.id === payload.journey?.id ? payload.journey : journey));
  });
  useInterval(() => { if (activeEmergency && ['ACTIVE', 'ACKNOWLEDGED'].includes(activeEmergency.status)) void (async () => { const location = await getLocation(); if (!location) { setLocationLive(false); return; } try { await api.emergencyLocation(activeEmergency.id, location); setLocationLive(true); } catch { setLocationLive(false); } })(); }, activeEmergency ? 30_000 : null);

  useEffect(() => { if (!showSos) return; if (sosSeconds <= 0) { setShowSos(false); void activateSos(); return; } const timer = window.setTimeout(() => setSosSeconds((value) => value - 1), 1000); return () => window.clearTimeout(timer); }, [showSos, sosSeconds]);
  const activateSos = async () => {
    try {
      const location = await getLocation();
      const result = await api.createEmergency({ source: 'SOS', location });
      setActiveEmergency(result.emergency); setShareUrl(result.shareUrl); setLocationLive(Boolean(location)); setView('emergency');
      notify(result.emergency.deliveryState === 'DELIVERED' ? `Emergency alert sent to ${result.emergency.contactCount} trusted contact${result.emergency.contactCount === 1 ? '' : 's'}.` : 'Emergency created, but contact delivery is not confirmed. Check your connection and provider settings.', result.emergency.deliveryState === 'DELIVERED' ? 'success' : 'danger');
      void loadData(true);
    } catch (err) { notify(err instanceof ApiError ? err.message : 'The alert could not be created. Please try again.', 'danger'); }
  };
  const activateSilentSos = async () => {
    try {
      const location = await getLocation();
      const result = await api.createEmergency({ source: 'SILENT_SOS', location });
      setActiveEmergency(result.emergency); setShareUrl(result.shareUrl); setLocationLive(Boolean(location)); setView('emergency');
      notify(result.emergency.deliveryState === 'DELIVERED' ? 'Discreet alert sent to your trusted circle.' : 'Discreet alert was created, but delivery is not confirmed.', result.emergency.deliveryState === 'DELIVERED' ? 'success' : 'danger');
      void loadData(true);
    } catch (err) { notify(err instanceof ApiError ? err.message : 'The discreet alert could not be created.', 'danger'); }
  };
  const beginSos = () => { if (activeEmergency) { setView('emergency'); return; } setSosSeconds(settings.sosCountdown); setShowSos(true); };
  const cancelSos = () => { setShowSos(false); setSosSeconds(settings.sosCountdown); notify('SOS cancelled. No alert was created.', 'info'); };
  const resolveEmergency = async () => { if (!activeEmergency) return; try { const result = await api.resolveEmergency(activeEmergency.id); setActiveEmergency(null); setView('overview'); notify('Marked safe. Location sharing has stopped.'); void loadData(true); } catch (err) { notify(err instanceof ApiError ? err.message : 'Could not resolve the emergency.', 'danger'); } };
  const cancelEmergency = async () => { if (!activeEmergency) return; try { await api.cancelEmergency(activeEmergency.id); setActiveEmergency(null); setView('overview'); notify('Emergency cancelled. Trusted contacts were updated.'); void loadData(true); } catch (err) { notify(err instanceof ApiError ? err.message : 'Could not cancel the emergency.', 'danger'); } };
  const startJourney = async (id: string) => { try { const result = await api.startJourney(id); setJourneys((current) => current.map((journey) => journey.id === id ? result.journey : journey)); notify('Journey started. Location sharing is now active for this journey.'); } catch (err) { notify(err instanceof ApiError ? err.message : 'Could not start journey.', 'danger'); } };
  const endJourney = async (id: string) => { try { const result = await api.endJourney(id); setJourneys((current) => current.map((journey) => journey.id === id ? result.journey : journey)); notify('Journey ended safely.'); } catch (err) { notify(err instanceof ApiError ? err.message : 'Could not end journey.', 'danger'); } };
  const confirmTimer = async (id: string) => { try { await api.confirmTimer(id); setTimers((current) => current.map((timer) => timer.id === id ? { ...timer, status: 'CONFIRMED' } : timer)); notify('Check-in sent. Your trusted circle can see that you are safe.'); } catch (err) { notify(err instanceof ApiError ? err.message : 'Could not send your check-in.', 'danger'); } };
  const setPage = (next: View) => { setView(next); setMobileNav(false); };
  const activeJourney = journeys.find((journey) => journey.status === 'ACTIVE');
  const runningTimer = timers.find((timer) => ['RUNNING', 'GRACE'].includes(timer.status));

  if (loading) return <div className="boot-screen"><Logo /><div className="boot-loader"><span /><span /><span /></div><p>Loading your safety overview…</p></div>;
  return <div className={`app-shell ${activeEmergency ? 'app-shell--emergency' : ''}`}>
    <aside className={`sidebar ${mobileNav ? 'sidebar--open' : ''}`}>
      <div className="sidebar-top"><Logo /><IconButton label="Close menu" className="mobile-close" onClick={() => setMobileNav(false)}><X size={18} /></IconButton></div>
      <div className="privacy-banner"><span className="privacy-icon"><Lock size={14} /></span><span><strong>Privacy mode</strong><small>Location sharing is off</small></span><span className="status-pip" /></div>
      <nav className="sidebar-nav" aria-label="Main navigation">
        <NavItem icon={<Home size={18} />} label="Overview" active={view === 'overview'} onClick={() => setPage('overview')} />
        <NavItem icon={<Siren size={18} />} label="Emergency" active={view === 'emergency'} onClick={() => setPage('emergency')} alert={Boolean(activeEmergency)} />
        <NavItem icon={<Route size={18} />} label="Safe journeys" active={view === 'journeys'} onClick={() => setPage('journeys')} badge={journeys.filter((item) => item.status === 'ACTIVE').length || undefined} />
        <NavItem icon={<Timer size={18} />} label="Safety timer" active={view === 'timer'} onClick={() => setPage('timer')} badge={runningTimer ? '·' : undefined} />
        <NavItem icon={<UsersRound size={18} />} label="Trusted circle" active={view === 'contacts'} onClick={() => setPage('contacts')} />
        <NavItem icon={<LifeBuoy size={18} />} label="Nearby help" active={view === 'resources'} onClick={() => setPage('resources')} />
        <NavItem icon={<NotebookTabs size={18} />} label="Safety history" active={view === 'history'} onClick={() => setPage('history')} />
        {user.role === 'ADMIN' && <div className="nav-divider"><span>Operations</span></div>}
        {user.role === 'ADMIN' && <NavItem icon={<Activity size={18} />} label="Admin overview" active={view === 'admin'} onClick={() => setPage('admin')} />}
      </nav>
      <div className="sidebar-bottom"><button className="support-link" onClick={() => notify('Support is available 24/7 in production. Configure your support channel in the deployment settings.', 'info')}><CircleHelp size={16} /><span>Need help?</span><ChevronRight size={14} /></button><div className="sidebar-user"><div className="avatar avatar--small">{user.firstName[0]}</div><div><strong>{user.fullName}</strong><span>{user.role === 'ADMIN' ? 'Operations admin' : 'Personal account'}</span></div><IconButton label="More account options"><Ellipsis size={17} /></IconButton></div></div>
    </aside>
    {mobileNav && <div className="sidebar-scrim" onClick={() => setMobileNav(false)} />}
    <main className="main-content">
      <header className="topbar"><div className="topbar-left"><IconButton label="Open menu" className="mobile-menu" onClick={() => setMobileNav(true)}><Menu size={20} /></IconButton><div className="breadcrumb"><span>My safety space</span><ChevronRight size={14} /><strong>{view === 'overview' ? 'Overview' : view === 'admin' ? 'Operations' : view.charAt(0).toUpperCase() + view.slice(1)}</strong></div></div><div className="topbar-actions"><LocationBadge live={Boolean(activeEmergency) || Boolean(activeJourney)} /><button className="notification-button" aria-label="Notifications" onClick={() => notify(notifications.length ? `${notifications.length} recent safety updates` : 'You are all caught up.', 'info')}><Bell size={18} />{notifications.filter((item) => item.status !== 'DELIVERED').length > 0 && <span />}</button><button className="topbar-avatar" onClick={() => setPage('settings')} aria-label="Open profile">{user.firstName[0]}</button></div></header>
      {error && <div className="connectivity-banner"><TriangleAlert size={16} /><span>{error}</span><button onClick={() => void loadData(true)}><RefreshCw size={14} /> Retry</button></div>}
      <div className="page-content">
        {view === 'overview' && <Overview user={user} contacts={contacts} activeEmergency={activeEmergency} activeJourney={activeJourney} runningTimer={runningTimer} journeys={journeys} notifications={notifications} onSos={beginSos} onNavigate={setPage} onConfirmTimer={confirmTimer} />}
        {view === 'emergency' && <EmergencyPage user={user} emergency={activeEmergency} shareUrl={shareUrl} locationLive={locationLive} onSos={beginSos} onSilentSos={activateSilentSos} onResolve={resolveEmergency} onCancel={cancelEmergency} onNavigate={setPage} notify={notify} />}
        {view === 'journeys' && <JourneysPage journeys={journeys} contacts={contacts} onStart={startJourney} onEnd={endJourney} onReload={() => void loadData(true)} notify={notify} />}
        {view === 'timer' && <TimerPage timers={timers} onConfirm={confirmTimer} onReload={() => void loadData(true)} notify={notify} />}
        {view === 'contacts' && <ContactsPage contacts={contacts} setContacts={setContacts} notify={notify} />}
        {view === 'resources' && <ResourcesPage resources={resources} />}
        {view === 'history' && <HistoryPage history={history} />}
        {view === 'settings' && <SettingsPage user={user} settings={settings} setUser={setUser} notify={notify} onLogout={onLogout} />}
        {view === 'admin' && user.role === 'ADMIN' && <AdminPage notify={notify} />}
      </div>
    </main>
    {showSos && <SosCountdown seconds={sosSeconds} onCancel={cancelSos} onActivateNow={() => { setShowSos(false); void activateSos(); }} />}
    {toast && <Toast message={toast.message} tone={toast.tone} onClose={() => setToast(null)} />}
  </div>;
}

function NavItem({ icon, label, active, onClick, badge, alert }: { icon: React.ReactNode; label: string; active?: boolean; onClick: () => void; badge?: string | number; alert?: boolean }) { return <button className={`nav-item ${active ? 'active' : ''}`} onClick={onClick}>{icon}<span>{label}</span>{alert && <i className="nav-alert" />}{badge !== undefined && !alert && <b>{badge}</b>}</button>; }

function Overview({ user, contacts, activeEmergency, activeJourney, runningTimer, journeys, notifications, onSos, onNavigate, onConfirmTimer }: { user: User; contacts: Contact[]; activeEmergency: Emergency | null; activeJourney?: Journey; runningTimer?: SafetyTimer; journeys: Journey[]; notifications: Notification[]; onSos: () => void; onNavigate: (view: View) => void; onConfirmTimer: (id: string) => void }) {
  const [nowTick, setNowTick] = useState(Date.now());
  useEffect(() => { const timer = window.setInterval(() => setNowTick(Date.now()), 30_000); return () => window.clearInterval(timer); }, []);
  const timerRemaining = runningTimer ? Math.max(0, new Date(runningTimer.expiresAt).getTime() - nowTick) : 0;
  const minutes = Math.floor(timerRemaining / 60_000);
  const seconds = Math.floor((timerRemaining % 60_000) / 1000).toString().padStart(2, '0');
  return <>
    <div className="welcome-row"><div><span className="eyebrow">{new Date().toLocaleDateString('en-IN', { weekday: 'long', day: 'numeric', month: 'long' })}</span><h1>Good evening, {user.firstName}<span className="wave">✦</span></h1><p>Your safety space is calm and ready when you need it.</p></div><div className="welcome-actions"><Pill tone="success" dot>All systems ready</Pill><Button variant="soft" icon={<Settings2 size={16} />} onClick={() => onNavigate('settings')}>Settings</Button></div></div>
    {activeEmergency ? <div className="emergency-strip"><div className="emergency-strip-icon"><Radio size={20} /></div><div><strong>Emergency active</strong><span>Trusted contacts have been notified. Location sharing is live.</span></div><Button variant="danger" size="sm" icon={<ArrowRight size={15} />} onClick={() => onNavigate('emergency')}>Open emergency</Button></div> : <div className="hero-grid"><div className="sos-card"><div className="sos-card-copy"><span className="eyebrow eyebrow--light">Need help now?</span><h2>One tap.<br /><em>Trusted support.</em></h2><p>Hold steady. ABHAYA will give you a moment to cancel before notifying your circle.</p><div className="sos-trust"><ShieldCheck size={16} /><span>Your location is <strong>not shared</strong> until you activate a session.</span></div></div><button className="sos-button" onClick={onSos} aria-label="Activate SOS"><span className="sos-ring sos-ring--one" /><span className="sos-ring sos-ring--two" /><span className="sos-inner"><Siren size={31} /><strong>SOS</strong><small>Tap for help</small></span></button><div className="sos-card-foot"><span><Vibrate size={14} /> Haptic-ready</span><span><Phone size={14} /> Call 112</span><span><Lock size={14} /> Private</span></div></div><div className="journey-map-card"><div className="map-card-top"><div><span className="eyebrow">{activeJourney ? 'Active journey' : 'Your area'}</span><h3>{activeJourney ? activeJourney.title : 'Ready when you are'}</h3></div><IconButton label="Open nearby help" onClick={() => onNavigate('resources')}><MoreHorizontal /></IconButton></div><MiniMap markers={activeJourney ? 1 : 4} active={Boolean(activeJourney)} /><div className="map-card-bottom">{activeJourney ? <><div className="route-meta"><span className="route-status"><span className="live-dot" /> Live journey</span><strong>{activeJourney.progress}% complete</strong></div><div className="route-line"><span style={{ width: `${activeJourney.progress}%` }} /></div><div className="route-foot"><span>{activeJourney.destination}</span><strong>{activeJourney.eta ?? '—'}</strong></div></> : <><span className="map-safe"><MapPin size={15} /> Location sharing is off</span><button onClick={() => onNavigate('journeys')}>Plan a journey <ArrowRight size={14} /></button></>}</div></div></div>}
    <div className="quick-actions"><QuickLink icon={<Route size={19} />} title="Start journey" description="Share a route, temporarily" onClick={() => onNavigate('journeys')} accent="green" /><QuickLink icon={<Timer size={19} />} title="Safety timer" description="Check on me in X minutes" onClick={() => onNavigate('timer')} accent="violet" /><QuickLink icon={<UsersRound size={19} />} title="Trusted circle" description={`${contacts.filter((contact) => contact.verified).length} verified contacts`} onClick={() => onNavigate('contacts')} accent="blue" /><QuickLink icon={<LifeBuoy size={19} />} title="Nearby help" description="Hospitals, police & more" onClick={() => onNavigate('resources')} accent="amber" /><QuickLink icon={<Phone size={19} />} title="Fake call" description="Create a safe exit" onClick={() => onNavigate('settings')} accent="rose" /><QuickLink icon={<Camera size={19} />} title="Evidence mode" description="Record only when you choose" onClick={() => onNavigate('emergency')} accent="slate" /></div>
    <div className="dashboard-lower"><Card className="timer-card"><CardHeader eyebrow="Safety timer" title={runningTimer ? runningTimer.label : 'No active timer'} action={<button className="text-button" onClick={() => onNavigate('timer')}>{runningTimer ? 'Manage' : 'Set timer'} <ArrowRight size={14} /></button>} />{runningTimer ? <div className="timer-card-body"><div className="timer-circle"><span>{minutes}:{seconds}</span><small>remaining</small></div><div className="timer-copy"><Pill tone={runningTimer.status === 'GRACE' ? 'warning' : 'info'} dot>{runningTimer.status === 'GRACE' ? 'Confirm now' : 'Running quietly'}</Pill><p>Your circle will be notified only if you miss the check-in and grace period.</p><div className="timer-actions"><Button size="sm" variant="primary" onClick={() => onConfirmTimer(runningTimer.id)} icon={<Check size={14} />}>I’m safe</Button><button className="subtle-link" onClick={() => onNavigate('timer')}>Extend timer</button></div></div></div> : <div className="timer-empty"><div className="empty-icon"><Clock3 size={20} /></div><div><strong>Set a quiet check-in</strong><p>“Check on me in 15 minutes.” No location sharing until you choose a session.</p></div><Button variant="soft" size="sm" onClick={() => onNavigate('timer')}>Set timer</Button></div>}</Card><Card className="activity-card"><CardHeader eyebrow="Recent activity" title="Your safety pulse" action={<button className="text-button" onClick={() => onNavigate('history')}>View history <ArrowRight size={14} /></button>} /><div className="activity-list">{notifications.slice(0, 3).map((notification) => <div className="activity-item" key={notification.id}><span className={`activity-icon activity-icon--${notification.type.includes('JOURNEY') ? 'green' : notification.type.includes('CHECK') ? 'blue' : 'violet'}`}>{notification.type.includes('JOURNEY') ? <Route size={15} /> : notification.type.includes('CHECK') ? <CheckCircle2 size={15} /> : <Bell size={15} />}</span><span className="activity-copy"><strong>{notification.title}</strong><small>{notification.body}</small></span><span className="activity-time"><TimeAgo date={notification.createdAt} /></span></div>)}{notifications.length === 0 && <EmptyState title="Nothing new" description="Your latest safety updates will appear here." />}</div></Card></div>
    <div className="privacy-note"><Lock size={15} /><span><strong>Your privacy is the default.</strong> ABHAYA never continuously shares your location. Start a journey, timer, or emergency session whenever you want support.</span><button onClick={() => onNavigate('settings')}>Review privacy settings</button></div>
  </>;
}

function SosCountdown({ seconds, onCancel, onActivateNow }: { seconds: number; onCancel: () => void; onActivateNow: () => void }) { return <div className="sos-overlay"><div className="sos-countdown-modal"><div className="countdown-badge"><Siren size={24} /></div><span className="eyebrow eyebrow--light">Emergency activation</span><h2>Are you sure you need help?</h2><p>Your trusted contacts will be notified and live location will begin when the countdown ends.</p><div className="countdown-number">{seconds}</div><span className="countdown-label">Not cancelled yet</span><div className="countdown-actions"><Button variant="soft" size="lg" onClick={onCancel} icon={<X size={17} />}>Cancel SOS</Button><Button variant="danger" size="lg" onClick={onActivateNow} icon={<Siren size={17} />}>Send now</Button></div><div className="countdown-safety"><Lock size={13} /> Alert delivery status will be shown clearly. No false confirmations.</div></div></div>; }

function EmergencyPage({ user, emergency, shareUrl, locationLive, onSos, onSilentSos, onResolve, onCancel, onNavigate, notify }: { user: User; emergency: Emergency | null; shareUrl: string; locationLive: boolean; onSos: () => void; onSilentSos: () => void; onResolve: () => void; onCancel: () => void; onNavigate: (view: View) => void; notify: (message: string, tone?: ToastTone) => void }) {
  const [evidence, setEvidence] = useState(false);
  const copyLink = async () => { if (!shareUrl) return; try { await navigator.clipboard.writeText(`${window.location.origin}${shareUrl}`); notify('Secure emergency link copied. It expires automatically.'); } catch { notify('Copy failed. You can share the link from your browser.', 'info'); } };
  return <><SectionHeading kicker="Emergency" title={emergency ? 'You are not alone.' : 'Ready when you need it'} description={emergency ? 'Keep this screen open if it is safe to do so. Your circle can see your latest status.' : 'Use SOS for urgent support. You remain in control at every step.'} action={emergency ? <Pill tone="danger" dot>Emergency active</Pill> : <Pill tone="success" dot>Standby</Pill>} />
    {emergency ? <div className="emergency-layout"><Card className="emergency-status-card"><div className="emergency-status-top"><div className="emergency-pulse"><span /><Siren size={24} /></div><div><span className="eyebrow eyebrow--light">Live session</span><h2>Emergency active</h2><p>Started <TimeAgo date={emergency.activatedAt ?? emergency.createdAt} /> · {emergency.contactCount} trusted contacts</p></div><StatusDot status={emergency.status} /></div><div className="status-callout"><div className="status-callout-icon"><Radio size={17} /></div><div><strong>{emergency.deliveryState === 'DELIVERED' ? 'Alert delivery confirmed' : 'Delivery needs attention'}</strong><p>{emergency.deliveryState === 'DELIVERED' ? 'Your verified circle received the alert through the configured provider.' : 'The event exists, but not every notification has been confirmed. Try another channel or call directly.'}</p></div></div><div className="emergency-map-wrap"><MiniMap active markers={1} lat={emergency.location?.latitude} lng={emergency.location?.longitude} /><div className="map-live-badge"><span className="live-dot" />{locationLive ? 'Live location updating' : 'Using last known location'}</div></div><div className="location-detail"><div><span className="eyebrow">Last known location</span><strong>{emergency.location ? `${emergency.location.latitude.toFixed(4)}, ${emergency.location.longitude.toFixed(4)}` : 'Location unavailable'}</strong><small>{emergency.lastLocationAt ? `Updated ${new Date(emergency.lastLocationAt).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}` : 'Allow location permission to update'}</small></div><LocationBadge live={locationLive} /></div><div className="emergency-actions"><Button variant="danger" size="lg" icon={<Phone size={18} />} onClick={() => window.open('tel:112', '_self')}>Call emergency services</Button><Button variant="soft" size="lg" icon={<CheckCircle2 size={18} />} onClick={onResolve}>I’m safe · End emergency</Button><Button variant="outline" size="lg" icon={<UsersRound size={18} />} onClick={() => onNavigate('contacts')}>View trusted circle</Button></div><div className="emergency-secondary"><button onClick={copyLink}><Copy size={15} /> Share secure link</button><button onClick={() => setEvidence(true)}><FileAudio size={15} /> Start evidence mode</button><button onClick={onCancel}><X size={15} /> Cancel alert</button></div></Card><div className="emergency-side"><Card><CardHeader eyebrow="Fast actions" title="Keep support close" /><div className="emergency-side-actions"><button onClick={() => window.open('tel:112', '_self')}><span className="action-icon action-icon--red"><Phone size={17} /></span><span><strong>Call 112</strong><small>Connect to local emergency services</small></span><ArrowRight size={15} /></button><button onClick={() => onNavigate('contacts')}><span className="action-icon action-icon--blue"><UsersRound size={17} /></span><span><strong>Trusted circle</strong><small>{emergency.contactCount} contacts configured</small></span><ArrowRight size={15} /></button><button onClick={copyLink}><span className="action-icon action-icon--green"><Globe2 size={17} /></span><span><strong>Emergency link</strong><small>Temporary and revocable</small></span><ArrowRight size={15} /></button></div></Card><Card className="privacy-card"><Lock size={18} /><strong>Private, temporary sharing</strong><p>Live location automatically stops when you resolve this emergency. Public links never include medical information.</p></Card></div></div> : <Card className="emergency-ready"><div className="ready-illustration"><ShieldCheck size={45} /><span>1107</span></div><h2>When you need help, you can reach it fast.</h2><p>Tap SOS to start a short cancellation countdown. If you do not cancel, we create an alert, start live location, and notify your trusted circle.</p><div className="ready-points"><span><Check size={15} /> Clear delivery status</span><span><Check size={15} /> Location sharing only for this session</span><span><Check size={15} /> Stop sharing when you mark safe</span></div><Button size="lg" variant="danger" icon={<Siren size={18} />} onClick={onSos}>Activate SOS</Button><button className="silent-link" onClick={onSilentSos}><Fingerprint size={15} /> Use discreet in-app trigger</button><button className="call-direct" onClick={() => window.open('tel:112', '_self')}><Phone size={15} /> Need immediate help? Call 112 directly</button></Card>}
    {evidence && <EvidenceModal emergencyId={emergency?.id} onClose={() => setEvidence(false)} notify={notify} />}
  </>;
}

function EvidenceModal({ emergencyId, onClose, notify }: { emergencyId?: string; onClose: () => void; notify: (message: string, tone?: ToastTone) => void }) {
  const [type, setType] = useState<'AUDIO' | 'VIDEO'>('AUDIO');
  const [consent, setConsent] = useState(false);
  const [status, setStatus] = useState<'idle' | 'starting' | 'recording' | 'saved'>('idle');
  const [evidenceId, setEvidenceId] = useState<string>();
  const recorder = useRef<MediaRecorder | undefined>(undefined);
  const stream = useRef<MediaStream | undefined>(undefined);
  const chunks = useRef<Blob[]>([]);
  const start = async () => {
    if (!consent) return;
    setStatus('starting');
    try {
      const mimeType = type === 'AUDIO' ? 'audio/webm' : 'video/webm';
      const session = await api.createEvidenceSession({ emergencyId, type, fileName: `abhaya-${Date.now()}.webm`, mimeType, sizeBytes: 1 });
      setEvidenceId(session.evidence.id);
      if (!navigator.mediaDevices?.getUserMedia || typeof MediaRecorder === 'undefined') {
        setStatus('saved');
        notify('Evidence session was created, but this browser cannot record media. Configure a supported device or mobile capture.', 'info');
        return;
      }
      stream.current = await navigator.mediaDevices.getUserMedia(type === 'AUDIO' ? { audio: true } : { audio: true, video: true });
      recorder.current = new MediaRecorder(stream.current, { mimeType });
      chunks.current = [];
      recorder.current.ondataavailable = (event) => { if (event.data.size) chunks.current.push(event.data); };
      recorder.current.onstop = () => { stream.current?.getTracks().forEach((track) => track.stop()); setStatus('saved'); void api.completeEvidence(session.evidence.id).catch(() => notify('Recording ended, but upload completion could not be confirmed.', 'danger')); };
      recorder.current.start();
      setStatus('recording');
    } catch (error) {
      stream.current?.getTracks().forEach((track) => track.stop());
      setStatus('idle');
      notify(error instanceof ApiError ? error.message : 'Recording permission was not granted or the session could not start.', 'danger');
    }
  };
  const stop = () => { if (recorder.current?.state === 'recording') recorder.current.stop(); else setStatus('saved'); };
  return <Modal title="Evidence mode" onClose={() => { if (status === 'recording') stop(); onClose(); }}><div className="modal-note modal-note--warning"><TriangleAlert size={17} /><span>Only start recording when you explicitly choose to. Camera and microphone permissions are required; this is never activated in the background.</span></div>{status === 'recording' ? <div className="recording-state"><span className="recording-dot" /><strong>{type === 'AUDIO' ? 'Audio' : 'Video'} recording is active</strong><small>Keep this screen open. Stop when you have captured what you need.</small><Button variant="danger" onClick={stop} icon={<SquareStopIcon />}>Stop and save</Button></div> : status === 'saved' ? <div className="recording-state recording-state--saved"><CheckCircle2 size={28} /><strong>Evidence session saved</strong><small>Session {evidenceId?.slice(0, 8) ?? 'created'} is restricted to your account. Configure S3 storage for encrypted media upload.</small><Button variant="soft" onClick={onClose}>Done</Button></div> : <><div className="evidence-choice"><button type="button" className={type === 'AUDIO' ? 'active' : ''} onClick={() => setType('AUDIO')}><FileAudio size={21} /><strong>Audio</strong><small>Lower visibility, voice capture</small></button><button type="button" className={type === 'VIDEO' ? 'active' : ''} onClick={() => setType('VIDEO')}><Camera size={21} /><strong>Video</strong><small>Capture with camera permission</small></button></div><label className="check-label terms"><input type="checkbox" checked={consent} onChange={(e) => setConsent(e.target.checked)} /><span>I understand this is an app-generated recording, access is restricted, and retention follows my privacy settings.</span></label><div className="modal-actions"><Button variant="outline" onClick={onClose}>Not now</Button><Button variant="dark" onClick={() => void start()} loading={status === 'starting'} disabled={!consent} icon={<Radio size={16} />}>Start {type.toLowerCase()} mode</Button></div></>}</Modal>;
}
function SquareStopIcon() { return <span style={{ display: 'inline-block', width: 12, height: 12, borderRadius: 3, background: 'currentColor' }} />;
}

function JourneysPage({ journeys, contacts, onStart, onEnd, onReload, notify }: { journeys: Journey[]; contacts: Contact[]; onStart: (id: string) => void; onEnd: (id: string) => void; onReload: () => void; notify: (message: string, tone?: ToastTone) => void }) {
  const [showCreate, setShowCreate] = useState(false); const [selected, setSelected] = useState<Journey | null>(null);
  return <><SectionHeading kicker="Temporary location sharing" title="Safe journeys" description="Share a route only for the time it takes. Anomalies ask for confirmation — they never label you as in danger automatically." action={<Button icon={<Plus size={17} />} onClick={() => setShowCreate(true)}>Plan a journey</Button>} />
    <div className="journey-explainer"><div className="journey-explainer-icon"><Route size={22} /></div><div><strong>Your location stays yours.</strong><span>It is shared only after you start a journey and stops when you arrive or end it.</span></div><LocationBadge /></div>
    {journeys.length === 0 ? <Card><EmptyState icon={<Route size={22} />} title="No journeys yet" description="Plan a route and optionally invite your trusted circle to follow along." action={<Button onClick={() => setShowCreate(true)}>Plan your first journey</Button>} /></Card> : <div className="journey-list">{journeys.map((journey) => <Card className={`journey-card ${journey.status === 'ACTIVE' ? 'journey-card--active' : ''}`} key={journey.id}><div className="journey-card-main"><div className={`journey-icon journey-icon--${journey.status === 'ACTIVE' ? 'active' : journey.status === 'COMPLETED' ? 'done' : 'planned'}`}>{journey.status === 'ACTIVE' ? <Navigation size={19} /> : journey.status === 'COMPLETED' ? <Check size={19} /> : <Route size={19} />}</div><div className="journey-info"><div className="item-title-row"><h3>{journey.title}</h3><StatusDot status={journey.status} /></div><div className="route-path"><span>{journey.origin}</span><ArrowRight size={14} /><strong>{journey.destination}</strong></div><div className="journey-meta"><span><CalendarClock size={14} /> Arrive by {new Date(journey.expectedArrival).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</span><span><UsersRound size={14} /> {journey.contactIds.length ? `${journey.contactIds.length} contacts` : 'Private route'}</span></div></div><IconButton label="Open journey details" onClick={() => setSelected(journey)}><Ellipsis size={18} /></IconButton></div>{journey.status === 'ACTIVE' && <><div className="journey-progress"><span style={{ width: `${journey.progress}%` }} /></div><div className="journey-progress-foot"><span>{journey.progress}% complete · {journey.distanceRemainingKm ?? '—'} km remaining</span><strong>ETA {journey.eta ?? '—'}</strong></div>{journey.anomaly && !journey.anomaly.acknowledged && <div className="anomaly-banner"><TriangleAlert size={16} /><span><strong>Check in with yourself.</strong> We noticed a possible {journey.anomaly.type.toLowerCase()} — this is not an emergency classification.</span><Button size="sm" variant="soft" onClick={async () => { try { await api.checkInJourney(journey.id, { message: 'I am safe' }); notify('Check-in sent. Thanks for confirming.', 'success'); onReload(); } catch { notify('Check-in could not be sent.', 'danger'); } }}>I’m safe</Button></div>}</>}{journey.status === 'PLANNED' && <div className="journey-card-actions"><Button size="sm" onClick={() => onStart(journey.id)} icon={<Navigation size={14} />}>Start journey</Button><button onClick={() => setSelected(journey)}>View details</button></div>}{journey.status === 'ACTIVE' && <div className="journey-card-actions"><Button size="sm" variant="soft" onClick={() => onEnd(journey.id)} icon={<Check size={14} />}>I’ve arrived</Button><button onClick={() => setSelected(journey)}>Manage journey</button></div>}</Card>)}</div>}
    {showCreate && <JourneyCreateModal contacts={contacts} onClose={() => setShowCreate(false)} onCreated={() => { setShowCreate(false); onReload(); notify('Journey saved. Start it when you are ready.'); }} notify={notify} />}
    {selected && <JourneyDetail journey={selected} onClose={() => setSelected(null)} onStart={onStart} onEnd={onEnd} />}
  </>;
}

function JourneyCreateModal({ contacts, onClose, onCreated, notify }: { contacts: Contact[]; onClose: () => void; onCreated: () => void; notify: (message: string, tone?: ToastTone) => void }) { const [form, setForm] = useState({ title: '', origin: '', destination: '', arrival: '', contactIds: [] as string[] }); const [loading, setLoading] = useState(false); const submit = async (e: React.FormEvent) => { e.preventDefault(); setLoading(true); try { await api.createJourney({ title: form.title, origin: form.origin, destination: form.destination, expectedArrival: new Date(form.arrival).toISOString(), contactIds: form.contactIds }); onCreated(); } catch (err) { notify(err instanceof ApiError ? err.message : 'Could not save journey.', 'danger'); } finally { setLoading(false); } }; const toggleContact = (id: string) => setForm((current) => ({ ...current, contactIds: current.contactIds.includes(id) ? current.contactIds.filter((item) => item !== id) : [...current.contactIds, id] })); return <Modal title="Plan a safe journey" onClose={onClose}><form onSubmit={submit} className="modal-form"><Field label="Journey name" placeholder="e.g. Evening class" value={form.title} onChange={(e) => setForm({ ...form, title: e.target.value })} required /><div className="form-grid"><Field label="Starting point" placeholder="e.g. Banjara Hills" value={form.origin} onChange={(e) => setForm({ ...form, origin: e.target.value })} required /><Field label="Destination" placeholder="e.g. Gachibowli" value={form.destination} onChange={(e) => setForm({ ...form, destination: e.target.value })} required /></div><Field label="Expected arrival" type="datetime-local" value={form.arrival} onChange={(e) => setForm({ ...form, arrival: e.target.value })} required /><div className="field"><span className="field-label">Who can follow? <small>(optional)</small></span><div className="contact-picker">{contacts.filter((contact) => contact.verified).map((contact) => <button type="button" key={contact.id} className={form.contactIds.includes(contact.id) ? 'selected' : ''} onClick={() => toggleContact(contact.id)}><span className="avatar avatar--tiny">{contact.name[0]}</span><span>{contact.name.split(' ')[0]}</span>{form.contactIds.includes(contact.id) && <Check size={14} />}</button>)}</div></div><div className="modal-note"><Lock size={15} /><span>Location sharing begins only when you press “Start journey”.</span></div><div className="modal-actions"><Button variant="outline" onClick={onClose}>Cancel</Button><Button type="submit" loading={loading} icon={<Route size={16} />}>Save journey</Button></div></form></Modal>; }
function JourneyDetail({ journey, onClose, onStart, onEnd }: { journey: Journey; onClose: () => void; onStart: (id: string) => void; onEnd: (id: string) => void }) { return <Modal title={journey.title} onClose={onClose}><div className="detail-map"><MiniMap active={journey.status === 'ACTIVE'} markers={1} /></div><div className="detail-route"><span>{journey.origin}</span><ArrowRight size={14} /><strong>{journey.destination}</strong></div><div className="detail-grid"><div><span>Expected arrival</span><strong>{new Date(journey.expectedArrival).toLocaleString([], { day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit' })}</strong></div><div><span>Status</span><StatusDot status={journey.status} /></div><div><span>Location sharing</span><strong>{journey.status === 'ACTIVE' ? 'Live' : 'Off'}</strong></div><div><span>Route progress</span><strong>{journey.progress}%</strong></div></div><div className="modal-actions">{journey.status === 'PLANNED' && <Button onClick={() => { onStart(journey.id); onClose(); }}>Start journey</Button>}{journey.status === 'ACTIVE' && <Button variant="soft" onClick={() => { onEnd(journey.id); onClose(); }}>I’ve arrived</Button>}<Button variant="outline" onClick={onClose}>Close</Button></div></Modal>; }

function TimerPage({ timers, onConfirm, onReload, notify }: { timers: SafetyTimer[]; onConfirm: (id: string) => void; onReload: () => void; notify: (message: string, tone?: ToastTone) => void }) { const [showCreate, setShowCreate] = useState(false); return <><SectionHeading kicker="Quiet support" title="Safety timer" description="Ask your circle to check on you after a set time. Confirmation is always requested before anyone is notified." action={<Button icon={<Plus size={17} />} onClick={() => setShowCreate(true)}>Set a timer</Button>} /><div className="timer-hero"><div className="timer-hero-icon"><Clock3 size={25} /></div><div><strong>“Check on me in X minutes.”</strong><p>Useful for walks, rides, meetings, or any moment you want a little extra accountability.</p></div><Pill tone="info" dot>Location off by default</Pill></div><div className="timer-list">{timers.map((timer) => <TimerRow key={timer.id} timer={timer} onConfirm={onConfirm} onReload={onReload} notify={notify} />)}{timers.length === 0 && <Card><EmptyState icon={<Timer size={22} />} title="No timers set" description="Give yourself a quiet safety net for the next few minutes." action={<Button onClick={() => setShowCreate(true)}>Set a timer</Button>} /></Card>}</div>{showCreate && <TimerCreateModal onClose={() => setShowCreate(false)} onCreated={() => { setShowCreate(false); onReload(); notify('Safety timer started.'); }} notify={notify} />}</>; }
function TimerRow({ timer, onConfirm, onReload, notify }: { timer: SafetyTimer; onConfirm: (id: string) => void; onReload: () => void; notify: (message: string, tone?: ToastTone) => void }) { const remaining = useCountdown(['RUNNING', 'GRACE'].includes(timer.status) ? timer.expiresAt : null); const minutes = Math.floor(remaining / 60_000); const seconds = Math.floor((remaining % 60_000) / 1000).toString().padStart(2, '0'); return <Card className={`timer-row ${timer.status === 'GRACE' ? 'timer-row--urgent' : ''}`}><div className="timer-row-icon"><Timer size={19} /></div><div className="timer-row-copy"><div className="item-title-row"><h3>{timer.label}</h3><StatusDot status={timer.status} /></div><p>{timer.status === 'RUNNING' ? `Check-in due in ${minutes}:${seconds}` : timer.status === 'GRACE' ? 'Your grace period is active — please confirm.' : timer.status === 'CONFIRMED' ? 'You checked in safely.' : 'Timer ended.'}</p><small>Created <TimeAgo date={timer.createdAt} /></small></div><div className="timer-row-actions">{['RUNNING', 'GRACE'].includes(timer.status) && <><Button size="sm" onClick={() => onConfirm(timer.id)} icon={<Check size={14} />}>I’m safe</Button><button onClick={async () => { try { await api.extendTimer(timer.id, 10); onReload(); notify('Timer extended by 10 minutes.'); } catch { notify('Could not extend timer.', 'danger'); } }}>+10 min</button><button onClick={async () => { try { await api.cancelTimer(timer.id); onReload(); notify('Timer cancelled.'); } catch { notify('Could not cancel timer.', 'danger'); } }}>Cancel</button></>}</div></Card>; }
function TimerCreateModal({ onClose, onCreated, notify }: { onClose: () => void; onCreated: () => void; notify: (message: string, tone?: ToastTone) => void }) { const [duration, setDuration] = useState(15); const [label, setLabel] = useState('Check on me'); const [loading, setLoading] = useState(false); const submit = async (e: React.FormEvent) => { e.preventDefault(); setLoading(true); try { await api.createTimer({ durationMinutes: duration, label }); onCreated(); } catch (err) { notify(err instanceof ApiError ? err.message : 'Could not create timer.', 'danger'); } finally { setLoading(false); } }; return <Modal title="Set a safety timer" onClose={onClose}><form onSubmit={submit} className="modal-form"><Field label="Label" value={label} onChange={(e) => setLabel(e.target.value)} placeholder="e.g. Walk home check-in" required /><div className="duration-options">{[5, 10, 15, 30].map((option) => <button type="button" className={duration === option ? 'active' : ''} key={option} onClick={() => setDuration(option)}>{option}<small>min</small></button>)}</div><Field label="Custom duration" type="number" min={1} max={1440} value={duration} onChange={(e) => setDuration(Number(e.target.value))} hint="You can pause or extend this later." /><div className="modal-note"><Bell size={15} /><span>At expiry, we will notify you first. Trusted contacts are only notified after the grace period if you do not confirm.</span></div><div className="modal-actions"><Button variant="outline" onClick={onClose}>Cancel</Button><Button type="submit" loading={loading} icon={<Timer size={16} />}>Start timer</Button></div></form></Modal>; }

function ContactsPage({ contacts, setContacts, notify }: { contacts: Contact[]; setContacts: (contacts: Contact[]) => void; notify: (message: string, tone?: ToastTone) => void }) { const [showCreate, setShowCreate] = useState(false); return <><SectionHeading kicker="Your people" title="Trusted circle" description="These are the people you choose to hear from your safety sessions. They never receive your location outside an active session." action={<Button icon={<Plus size={17} />} onClick={() => setShowCreate(true)}>Add contact</Button>} /><div className="circle-summary"><div className="circle-avatars">{contacts.slice(0, 4).map((contact) => <span className="avatar avatar--circle" key={contact.id}>{contact.name[0]}</span>)}</div><div><strong>{contacts.filter((contact) => contact.verified).length} verified contacts</strong><span>{contacts.length ? 'Ready to receive the alerts you choose.' : 'Add someone you trust for a little extra support.'}</span></div><div className="circle-security"><Lock size={15} /> No location outside a session</div></div><div className="contacts-grid">{contacts.map((contact) => <ContactCard contact={contact} key={contact.id} onChange={(next) => setContacts(contacts.map((item) => item.id === next.id ? next : item))} notify={notify} />)}{contacts.length === 0 && <Card><EmptyState icon={<UsersRound size={22} />} title="Your circle is empty" description="Add a friend, family member, or colleague who can be there when you need them." action={<Button onClick={() => setShowCreate(true)}>Add trusted contact</Button>} /></Card>}</div>{showCreate && <ContactCreateModal onClose={() => setShowCreate(false)} onCreated={(contact) => { setContacts([...contacts, contact]); setShowCreate(false); notify('Contact added. Send them the invitation to verify the connection.'); }} notify={notify} />}</>; }
function ContactCard({ contact, onChange, notify }: { contact: Contact; onChange: (contact: Contact) => void; notify: (message: string, tone?: ToastTone) => void }) { return <Card className="contact-card"><div className="contact-card-top"><span className="avatar avatar--large">{contact.name[0]}</span><div><h3>{contact.name}</h3><span>{contact.relationship}</span></div><IconButton label="Contact options"><Ellipsis size={18} /></IconButton></div><div className="contact-detail"><span><Phone size={14} /> {contact.phone}</span>{contact.email && <span><MessageCircle size={14} /> {contact.email}</span>}</div><div className="contact-status">{contact.verified ? <Pill tone="success" dot>Verified</Pill> : <Pill tone="warning" dot>Invitation pending</Pill>}<span>Priority {contact.priority}</span></div><div className="contact-receives"><span>Receives</span><div>{contact.receives.map((item) => <Pill key={item} tone="neutral">{item === 'EMERGENCY' ? 'Emergency' : item === 'JOURNEY' ? 'Journeys' : item === 'TIMER' ? 'Timers' : 'Check-ins'}</Pill>)}</div></div><div className="contact-card-actions"><button onClick={async () => { try { await api.testContact(contact.id); notify('Test notification recorded. No emergency was created.', 'info'); } catch { notify('Test notification failed.', 'danger'); } }}><Vibrate size={14} /> Send test</button><button onClick={async () => { try { const result = await api.updateContact(contact.id, { verified: true }); onChange(result.contact); notify('Contact marked verified for demo mode.'); } catch { notify('Could not update contact.', 'danger'); } }}>Edit details <ArrowRight size={14} /></button></div></Card>; }
function ContactCreateModal({ onClose, onCreated, notify }: { onClose: () => void; onCreated: (contact: Contact) => void; notify: (message: string, tone?: ToastTone) => void }) { const [form, setForm] = useState({ name: '', phone: '', email: '', relationship: 'Friend' }); const [loading, setLoading] = useState(false); const submit = async (e: React.FormEvent) => { e.preventDefault(); setLoading(true); try { const result = await api.addContact({ ...form, receives: ['EMERGENCY', 'JOURNEY', 'TIMER', 'CHECK_IN'] }); onCreated(result.contact); if (result.invitation?.token) notify('Contact added. Demo invitation token is available in the API response.', 'info'); } catch (err) { notify(err instanceof ApiError ? err.message : 'Could not add contact.', 'danger'); } finally { setLoading(false); } }; return <Modal title="Add a trusted contact" onClose={onClose}><form onSubmit={submit} className="modal-form"><div className="contact-form-intro"><span className="avatar avatar--large">{form.name ? form.name[0].toUpperCase() : <UserRound size={20} />}</span><p>Choose someone who can respond calmly if your journey, timer, or emergency session needs attention.</p></div><Field label="Name" placeholder="e.g. Maya Iyer" value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })} required /><Field label="Phone number" type="tel" placeholder="+91 90000 11007" value={form.phone} onChange={(e) => setForm({ ...form, phone: e.target.value })} required /><Field label="Email (optional)" type="email" placeholder="maya@example.com" value={form.email} onChange={(e) => setForm({ ...form, email: e.target.value })} /><SelectField label="Relationship" value={form.relationship} onChange={(e) => setForm({ ...form, relationship: e.target.value })}><option>Friend</option><option>Family</option><option>Partner</option><option>Colleague</option><option>Neighbour</option></SelectField><div className="modal-note"><ShieldCheck size={15} /><span>They will be invited to verify this connection. Until verified, they will not receive emergency alerts.</span></div><div className="modal-actions"><Button variant="outline" onClick={onClose}>Cancel</Button><Button type="submit" loading={loading} icon={<Plus size={16} />}>Add contact</Button></div></form></Modal>; }

function ResourcesPage({ resources }: { resources: Resource[] }) { const [filter, setFilter] = useState('ALL'); const filtered = resources.filter((resource) => filter === 'ALL' || resource.type === filter); return <><SectionHeading kicker="Verified support nearby" title="Nearby help" description="Find police, hospitals, pharmacies, and support resources near you. Distances are approximate until you allow location access." action={<Button variant="soft" icon={<Crosshair size={16} />} onClick={() => void getLocation()}>Use my location</Button>} /><div className="resource-layout"><Card className="resource-map-card"><MiniMap markers={filtered.length} /><div className="map-legend"><span><i className="legend-dot legend-dot--you" /> You</span><span><i className="legend-dot legend-dot--police" /> Police</span><span><i className="legend-dot legend-dot--help" /> Support</span></div></Card><div className="resource-list-panel"><div className="resource-filter"><button className={filter === 'ALL' ? 'active' : ''} onClick={() => setFilter('ALL')}>All</button><button className={filter === 'POLICE' ? 'active' : ''} onClick={() => setFilter('POLICE')}><Siren size={13} /> Police</button><button className={filter === 'HOSPITAL' ? 'active' : ''} onClick={() => setFilter('HOSPITAL')}><Hospital size={13} /> Hospitals</button><button className={filter === 'PHARMACY' ? 'active' : ''} onClick={() => setFilter('PHARMACY')}><Plus size={13} /> Pharmacies</button></div>{filtered.map((resource) => <div className="resource-row" key={resource.id}><span className={`resource-icon resource-icon--${resource.type.toLowerCase()}`}>{resource.type === 'POLICE' ? <Siren size={17} /> : resource.type === 'HOSPITAL' ? <Hospital size={17} /> : <LifeBuoy size={17} />}</span><div className="resource-copy"><div><strong>{resource.name}</strong>{resource.verified && <CheckCircle2 size={14} />}</div><span>{resource.address}</span><small>{resource.distanceKm.toFixed(1)} km away</small></div><div className="resource-actions">{resource.phone && <button onClick={() => window.open(`tel:${resource.phone}`, '_self')} aria-label={`Call ${resource.name}`}><Phone size={15} /></button>}<button onClick={() => window.open(`https://maps.google.com/?q=${resource.latitude},${resource.longitude}`, '_blank')} aria-label={`Get directions to ${resource.name}`}><Navigation size={15} /></button></div></div>)}{filtered.length === 0 && <EmptyState title="No resources in this filter" description="Try another category." />}</div></div><div className="resource-footnote"><ShieldCheck size={15} /><span>Resources are verified by ABHAYA administrators. In an immediate emergency, call local emergency services directly.</span><a href="tel:112">Call 112</a></div></>; }

function HistoryPage({ history }: { history: History | null }) { const [filter, setFilter] = useState<'ALL' | 'EMERGENCY' | 'JOURNEY' | 'CHECK_IN'>('ALL'); const rows = useMemo<HistoryRow[]>(() => { if (!history) return []; const items = [...history.emergencies.map((item) => ({ id: item.id, type: 'EMERGENCY', title: `${item.source === 'SILENT_SOS' ? 'Silent SOS' : 'SOS'} session`, status: item.status, date: item.createdAt, detail: item.location ? 'Location captured for this session' : 'No location captured' })), ...history.journeys.map((item) => ({ id: item.id, type: 'JOURNEY', title: item.title, status: item.status, date: item.createdAt, detail: `${item.origin} → ${item.destination}` })), ...history.checkIns.map((item) => ({ id: item.id, type: 'CHECK_IN', title: 'Safety check-in', status: 'CONFIRMED', date: item.createdAt, detail: item.message ?? 'I am safe' }))]; return items.filter((item) => filter === 'ALL' || item.type === filter).sort((a, b) => b.date.localeCompare(a.date)); }, [history, filter]); return <><SectionHeading kicker="Private record" title="Safety history" description="A private timeline of your journeys, check-ins, timers, and emergency sessions. Manage retention in settings." action={<Button variant="soft" icon={<Lock size={16} />}>Private history</Button>} /><div className="history-filters">{[['ALL', 'All activity'], ['EMERGENCY', 'Emergencies'], ['JOURNEY', 'Journeys'], ['CHECK_IN', 'Check-ins']].map(([value, label]) => <button key={value} className={filter === value ? 'active' : ''} onClick={() => setFilter(value as typeof filter)}>{label}</button>)}</div><Card className="history-card">{rows.length ? <div className="history-list">{rows.map((row) => <div className="history-row" key={`${row.type}-${row.id}`}><span className={`history-icon history-icon--${row.type.toLowerCase()}`}>{row.type === 'EMERGENCY' ? <Siren size={16} /> : row.type === 'JOURNEY' ? <Route size={16} /> : <Check size={16} />}</span><div className="history-copy"><strong>{row.title}</strong><span>{row.detail}</span></div><StatusDot status={row.status} /><span className="history-date"><TimeAgo date={row.date} /><small>{new Date(row.date).toLocaleDateString([], { day: 'numeric', month: 'short' })}</small></span><IconButton label="More history actions"><Ellipsis size={17} /></IconButton></div>)}</div> : <EmptyState icon={<NotebookTabs size={22} />} title="No activity found" description="Your private activity will appear here as you use your safety tools." />}</Card><div className="history-disclaimer"><Lock size={15} /><span>History is stored for your account only. Delete or shorten retention from Privacy settings.</span></div></>; }

function SettingsPage({ user, settings, setUser, notify, onLogout }: { user: User; settings: Settings; setUser: (user: User) => void; notify: (message: string, tone?: ToastTone) => void; onLogout: () => void }) { const [profile, setProfile] = useState({ fullName: user.fullName, phone: user.phone, city: user.city ?? '' }); const [saving, setSaving] = useState(false); const [fakeCall, setFakeCall] = useState(false); const saveProfile = async (e: React.FormEvent) => { e.preventDefault(); setSaving(true); try { const result = await api.updateProfile(profile); setUser({ ...user, ...result.user }); notify('Profile updated.'); } catch (err) { notify(err instanceof ApiError ? err.message : 'Could not save profile.', 'danger'); } finally { setSaving(false); } }; const updateSettings = async (patch: Partial<Settings>) => { try { const result = await api.updateSettings(patch); setUser({ ...user, settings: result.settings }); notify('Safety preferences saved.'); } catch { notify('Could not save that preference.', 'danger'); } }; return <><SectionHeading kicker="Control center" title="Settings" description="Tune your safety experience without losing the calm simplicity of the home screen." /><div className="settings-layout"><div className="settings-main"><Card><CardHeader eyebrow="Your profile" title="Personal details" /><form className="settings-profile" onSubmit={saveProfile}><div className="profile-avatar-wrap"><div className="avatar avatar--profile">{user.firstName[0]}</div><button type="button" onClick={() => notify('Profile photo upload is ready for S3 storage configuration.', 'info')}><Camera size={14} /> Change photo</button></div><div className="settings-profile-fields"><Field label="Full name" value={profile.fullName} onChange={(e) => setProfile({ ...profile, fullName: e.target.value })} /><Field label="Phone number" value={profile.phone} onChange={(e) => setProfile({ ...profile, phone: e.target.value })} /><Field label="City" value={profile.city} onChange={(e) => setProfile({ ...profile, city: e.target.value })} /><div className="settings-email"><span className="field-label">Email address</span><strong>{user.email}</strong><Pill tone="success" dot>Verified</Pill></div><Button type="submit" loading={saving} size="sm">Save profile</Button></div></form></Card><Card><CardHeader eyebrow="Safety defaults" title="How ABHAYA responds" /><div className="settings-list"><div className="settings-control"><div><strong>SOS cancellation countdown</strong><small>Time to cancel before contacts are notified</small></div><div className="number-stepper"><button onClick={() => void updateSettings({ sosCountdown: Math.max(0, settings.sosCountdown - 1) })}>−</button><strong>{settings.sosCountdown}s</strong><button onClick={() => void updateSettings({ sosCountdown: Math.min(30, settings.sosCountdown + 1) })}>+</button></div></div><div className="settings-control"><div><strong>Journey anomaly sensitivity</strong><small>Use signals to ask for confirmation, never to classify danger</small></div><SelectField label="Sensitivity" value={settings.deviationSensitivity} onChange={(e) => void updateSettings({ deviationSensitivity: e.target.value as Settings['deviationSensitivity'] })}><option value="low">Low</option><option value="medium">Balanced</option><option value="high">High</option></SelectField></div><Toggle label="Ask my trusted circle to help" description="Notify verified contacts after a missed confirmation." checked={settings.escalation.notifyContacts} onChange={(value) => void updateSettings({ escalation: { ...settings.escalation, notifyContacts: value } })} /></div></Card><Card><CardHeader eyebrow="Notifications" title="Choose your channels" /><div className="settings-list"><Toggle label="Push notifications" description="Fast alerts on your trusted devices" checked={settings.notificationPreferences.push} onChange={(value) => void updateSettings({ notificationPreferences: { ...settings.notificationPreferences, push: value } })} /><Toggle label="SMS fallback" description="Use SMS when a provider is configured" checked={settings.notificationPreferences.sms} onChange={(value) => void updateSettings({ notificationPreferences: { ...settings.notificationPreferences, sms: value } })} /><Toggle label="Email updates" description="Receipts, invitations, and security events" checked={settings.notificationPreferences.email} onChange={(value) => void updateSettings({ notificationPreferences: { ...settings.notificationPreferences, email: value } })} /></div></Card><Card><CardHeader eyebrow="A little breathing room" title="Fake call" action={<Pill tone="purple">Clearly simulated</Pill>} /><div className="fake-call-setting"><div className="fake-call-preview"><div className="avatar avatar--small">M</div><div><strong>Mom</strong><span>Incoming call simulation</span></div><Phone size={18} /></div><div><p>Create a simulated incoming call when you need an easy exit. It never contacts a real person or places a call.</p><Button variant="soft" size="sm" onClick={() => setFakeCall(true)} icon={<Phone size={15} />}>Preview fake call</Button></div></div></Card></div><aside className="settings-aside"><Card className="settings-security-card"><div className="settings-aside-icon"><ShieldCheck size={22} /></div><span className="eyebrow">Privacy snapshot</span><h3>You’re in control</h3><p>Location sharing is currently <strong>off</strong>. Your live location is only shared during an active emergency or journey.</p><div className="privacy-meter"><span style={{ width: '86%' }} /></div><small>86% of privacy controls are at their recommended default</small><button onClick={() => notify('Privacy policy placeholder — legal review required before production launch.', 'info')}>Read privacy policy <ArrowRight size={14} /></button></Card><Card><CardHeader eyebrow="Account security" title="Devices & sessions" /><div className="device-row"><span className="device-icon"><Globe2 size={17} /></span><div><strong>Chrome on this device</strong><span>Active now · Hyderabad</span></div><Pill tone="success" dot>Current</Pill></div><button className="settings-link" onClick={() => notify('Session management API is active. Other sessions can be revoked from the API.', 'info')}><KeyRound size={15} /> Manage sessions <ArrowRight size={14} /></button></Card><Card className="logout-card"><LogOut size={17} /><div><strong>Sign out</strong><p>Sign out of this device. Your safety sessions keep their server-side state.</p></div><button onClick={onLogout}>Sign out</button></Card></aside></div>{fakeCall && <FakeCallModal onClose={() => setFakeCall(false)} />}</>; }
function FakeCallModal({ onClose }: { onClose: () => void }) { return <div className="fake-call-overlay"><div className="fake-call-modal"><span className="fake-call-label"><Vibrate size={14} /> App-generated simulation</span><div className="avatar avatar--huge">M</div><h2>Mom</h2><p>Incoming simulated call</p><div className="fake-call-actions"><button className="fake-call-decline" onClick={onClose}><X size={22} /></button><button className="fake-call-answer" onClick={onClose}><Phone size={22} /></button></div><small>This does not contact a real person.</small></div></div>; }

function AdminPage({ notify }: { notify: (message: string, tone?: ToastTone) => void }) { const [overview, setOverview] = useState<import('./api').AdminOverview | null>(null); const [emergencies, setEmergencies] = useState<Emergency[]>([]); const [users, setUsers] = useState<User[]>([]); const [tab, setTab] = useState<'overview' | 'emergencies' | 'users' | 'resources'>('overview'); const [loading, setLoading] = useState(true); const load = async () => { setLoading(true); try { const [o, e, u] = await Promise.all([api.adminOverview(), api.adminEmergencies(), api.adminUsers()]); setOverview(o); setEmergencies(e.emergencies); setUsers(u.users); } catch { notify('Admin data could not be loaded.', 'danger'); } finally { setLoading(false); } }; useEffect(() => { void load(); }, []); if (loading) return <><SectionHeading kicker="Operations" title="Admin overview" description="Safety operations, incident health, and accountability." /><div className="admin-stats">{[1, 2, 3, 4].map((item) => <Card key={item}><Skeleton width="70px" height="28px" /><Skeleton width="120px" /></Card>)}</div></>; const stats = overview?.stats; return <><SectionHeading kicker="Operations" title="Safety command center" description="Monitor live system state without exposing unnecessary private account data." action={<Pill tone="success" dot>System healthy</Pill>} /><div className="admin-tabs">{[['overview', 'Overview'], ['emergencies', 'Emergencies'], ['users', 'Users'], ['resources', 'Resources']].map(([value, label]) => <button key={value} className={tab === value ? 'active' : ''} onClick={() => setTab(value as typeof tab)}>{label}</button>)}<Button size="sm" variant="soft" icon={<RefreshCw size={14} />} onClick={() => void load()}>Refresh</Button></div>{tab === 'overview' && <><div className="admin-stats"><AdminStat label="Total users" value={stats?.totalUsers ?? 0} icon={<UsersRound size={18} />} tone="blue" /><AdminStat label="Active emergencies" value={stats?.activeEmergencies ?? 0} icon={<Siren size={18} />} tone="red" /><AdminStat label="Active journeys" value={stats?.activeJourneys ?? 0} icon={<Route size={18} />} tone="green" /><AdminStat label="Delivery success" value={`${stats?.notificationDeliverySuccess ?? 0}%`} icon={<Bell size={18} />} tone="violet" /></div><div className="admin-grid"><Card><CardHeader eyebrow="Attention needed" title="Active emergencies" action={<button className="text-button" onClick={() => setTab('emergencies')}>View all <ArrowRight size={14} /></button>} />{(overview?.activeEmergencies ?? []).length ? overview?.activeEmergencies.map((emergency) => <div className="admin-incident" key={emergency.id}><span className="incident-pulse"><span /></span><div><strong>{emergency.user?.fullName ?? 'User'}</strong><span>{emergency.source} · <TimeAgo date={emergency.createdAt} /></span></div><StatusDot status={emergency.status} /></div>) : <EmptyState icon={<ShieldCheck size={22} />} title="No active emergencies" description="The current queue is clear." />}</Card><Card><CardHeader eyebrow="Today" title="System pulse" /><div className="system-pulse"><div><span>Resolved incidents</span><strong>{stats?.resolvedIncidents ?? 0}</strong></div><div><span>Cancelled incidents</span><strong>{stats?.cancelledIncidents ?? 0}</strong></div><div><span>Notification delivery</span><strong>{stats?.notificationDeliverySuccess ?? 0}%</strong></div><div><span>System errors</span><strong className="success-number">{stats?.systemErrors ?? 0}</strong></div></div></Card></div></>}{tab === 'emergencies' && <Card><CardHeader eyebrow="Incident queue" title="Emergency history" /><div className="admin-table">{emergencies.map((emergency) => <div className="admin-table-row" key={emergency.id}><div className="table-primary"><span className="table-icon table-icon--red"><Siren size={15} /></span><span><strong>{emergency.user?.fullName ?? 'User'}</strong><small>{emergency.source} · {new Date(emergency.createdAt).toLocaleString()}</small></span></div><StatusDot status={emergency.status} /><span>{emergency.deliveryState}</span>{!['RESOLVED', 'CANCELLED'].includes(emergency.status) ? <Button size="sm" variant="soft" onClick={async () => { await api.adminResolve(emergency.id); notify('Emergency resolved and user notified.'); void load(); }}>Resolve</Button> : <span className="muted-label">Closed</span>}</div>)}</div></Card>}{tab === 'users' && <Card><CardHeader eyebrow="Accounts" title="Users & roles" /><div className="admin-table">{users.map((account) => <div className="admin-table-row" key={account.id}><div className="table-primary"><span className="avatar avatar--tiny">{account.firstName[0]}</span><span><strong>{account.fullName}</strong><small>{account.email}</small></span></div><Pill tone={account.role === 'ADMIN' ? 'purple' : 'neutral'}>{account.role}</Pill><span>{account.city ?? '—'}</span><span className="muted-label">Active</span></div>)}</div></Card>}{tab === 'resources' && <Card><CardHeader eyebrow="Verified support" title="Safety resources" /><div className="resource-admin-grid">{['Police stations', 'Hospitals', 'Pharmacies', 'Shelters'].map((label, index) => <div key={label}><span className="admin-resource-number">{[1, 1, 1, 1][index]}</span><span>{label}</span><small>verified resource</small></div>)}</div><div className="admin-legal-note"><ShieldCheck size={16} /><span>Resource edits are audit logged. Verify phone numbers and addresses before publishing.</span></div></Card>}</>; }
function AdminStat({ label, value, icon, tone }: { label: string; value: string | number; icon: React.ReactNode; tone: string }) { return <Card className="admin-stat"><span className={`admin-stat-icon admin-stat-icon--${tone}`}>{icon}</span><strong>{value}</strong><span>{label}</span><small>vs. last 30 days <ArrowRight size={12} /></small></Card>; }
